 * browser blocks autoplay (then audio starts on the first click or key press).
 */
export function Narrator() {
  const [intro, setIntro] = useState<Narration | null>(null);
  const [t, setT] = useState(0);
  const [playing, setPlaying] = useState(false);
  const [muted, setMuted] = useState(false);
  const [blocked, setBlocked] = useState(false);
  const [duration, setDuration] = useState<number | null>(null);
  const [open, setOpen] = useState(true);
  const [expanded, setExpanded] = useState(false); // hover shows the whole intro
  const audio = useRef<HTMLAudioElement | null>(null);
  const tRef = useRef(0);

  useEffect(() => {
    if (playing && done) setPlaying(false);
  }, [playing, done]);

  useEffect(() => {
    if (!done || playing) return;
    const timer = setTimeout(() => setOpen(false), COLLAPSE_MS);
    return () => clearTimeout(timer);
  }, [done, playing]);

  // Autoplay blocked: start the audio, in sync with the captions, on the first interaction.
  useEffect(() => {
    if (!blocked || !playing) return;
    const unlock = () => startAudio(tRef.current);
    window.addEventListener("pointerdown", unlock, { once: true });
    window.addEventListener("keydown", unlock, { once: true });
    return () => {
      window.removeEventListener("pointerdown", unlock);
      window.removeEventListener("keydown", unlock);
    };
  }, [blocked, playing, startAudio]);

  const replay = useCallback(() => {
    setT(0);
    setOpen(true);
    setPlaying(true);
    startAudio(0);
  }, [startAudio]);
.agentpick__stop { background: var(--coral); }
.agentpick .btn:disabled { opacity: 0.45; cursor: default; }
.agent__hint { font-size: 10.5px; line-height: 1.3; margin-top: -6px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
/* Right column ends above the (expanded) narrator card; the agent's code block gives way first. */
.app__right { bottom: 250px; }
.app__right > .card { flex: none; }
.app__right > .card:has(.agentpick) { flex: 0 1 auto; min-height: 0; overflow: hidden; }
.app__right > .card:has(.agentpick) > :not(.code) { flex-shrink: 0; }
.app__right .code { flex: 0 1 auto; min-height: 0; }
.agent__now { display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; } /* long notes must not push the panel onto the narrator */

.frozen > :not(.frozen__lock) { opacity: 0.45; filter: saturate(0.5); pointer-events: none; user-select: none; }
.frozen__lock { position: absolute; z-index: 2; top: -9px; right: -9px; width: 22px; height: 22px; border-radius: 50%; background: var(--ink); color: #fff; display: grid; place-items: center; box-shadow: var(--shadow-pop); }
.app__left > .frozen__lock { top: 4px; right: 16px; }

